    沉陆: ['芦塘', '潮沼', '泥屿', '浅滩', '沉舟'],
    盐岸: ['盐湖', '盐屯', '晒场', '堤口', '胶湾'],
    灰野: ['大仓', '麦岭', '安原', '河渡', '中垒'],
    黑岭: ['黑窑', '大岭', '砾原', '石关', '稳岩'],
    霜脊: ['霜林', '寒谷', '冰河', '雪屯', '冷杉'],
    雾谷: ['雾岭', '云关', '岩谷', '苔谷', '隼岩'],
    风碛: ['铁沙', '砾滩', '醴泉', '阳关', '金垒'],
    藤林: ['潮林', '苍藤', '南陲', '九藤', '日港'],
    潮湾: ['江湾', '汊口', '丹浦', '会浦', '章港'],
    泽心: ['泽畔', '芦洲', '沙洲', '菱湖', '水屯'],
    碎垣: ['残桥', '望楼', '梁墟', '沛垒', '谯墟'],
