    scope: ['fort', 'county', 'jun', 'zhou', 'capital'],   /* v89.204：全部城市纳入围攻（名城不再是决战制） */
    repairPerDay: 8,                /* 每整日民心恢复（%）：围而不攻会前功尽弃 */
