  DATA.GUARD_FOLD_V2 = { dim: 1, staPct: 1, atkDim: 1 };   /* v91.88：**取消差异系数**（老板） */
  /* 索引 = 野地等级 −1（v91.89：扩到 15 级，11~15 全部天启体） */
  DATA.GUARD_RANK_LADDER = ['ying', 'ying', 'ying', 'ming', 'ming', 'ming', 'ming', 'tian', 'tian', 'tian', 'tian', 'tian', 'tian', 'tian', 'tian'];
