    g.id = 'lord';                     /* 稳定 id：'lord' 不匹配 /^(g|cd)\d+$/，不与 nextGenId 撞车 */
    g.isLord = true;
    g.name = r.name || g.name;
    g.gender = r.gender || 'male';
