    var _m196 = (_st196 && _st196.mul) || { tong: 1, nz: 1, yw: 1, zm: 1 };
    var _msum196 = (_m196.tong + _m196.nz + _m196.yw + _m196.zm) || 4;
    var _f196 = 4 / _msum196;
