    var _ct191 = (tq.cityId && GAME.cityById(tq.cityId)) || GAME.mainCityOf() || (s.cities || [])[0] || null;
    var _tt191 = _ct191 ? GAME.techsOf(_ct191) : null;
    if (_tt191) _tt191[tq.techId] = (_tt191[tq.techId] || 0) + 1;
    GAME.statBump('techDone', 1);
