  GAME.buildBonusNum = function (key) {
    var out = 0, b = GAME.buildOf();
    for (var k in b) {
      var m = GAME.buildModuleOf(b[k]);
      if (m && m.buff && m.buff[key]) out += m.buff[key];
    }
    return out;
  };

  GAME.autoMarch = function () {
    var s = GAME.state;
    var cfg = GAME.autoMarchCfg();
    if (!cfg || !cfg.on) return null;
    var now = U.now();
    if (now - (cfg.last || 0) < cfg.everyMin * 60000) return null;
    cfg.last = now;
    var done = 0, lastMsg = '';
    (s.cities || []).forEach(function (city) {
      var r = GAME.autoMarchOnce(cfg, city);
      if (r && r.ok) { done++; lastMsg = r.msg; }
      else if (r && r.msg && !lastMsg) lastMsg = r.msg;
    });
    s.autoMarchInfo = { ok: done > 0, msg: done > 0 ? ('已派 ' + done + ' 城出征') : (lastMsg || '待命'), at: now };
    if (done > 0) GAME.log('🤖 自动出征：' + done + ' 城各派一支（各用各城资源与队列）');
    return { ok: done > 0, msg: s.autoMarchInfo.msg };
  };

  /* ============================================================
   * v91.59（老板）：「增加自动采购功能，可以设定所有商品的数量，每现实日均购买 X 件」——
   *   · `s.settings.autoBuy = { on, targets:{itemId:qty}, everyMin, last }`（逐商品目标持有量）。
   *   · 主循环节流（现实分钟）；逐商品把持有补到目标（受**每日购买上限**与旧币钳制）。
   *   · 走同一出口 GAME.doShopping（silent）→ 每日上限/扣款/日志自动一致。
   *   · **仅在线 tick**（与 autoMarch 同轴，见 state.js）—— 不吃离线补算，避免回档瞬间爆买。
   * ============================================================ */
  /* v91.72（老板）：「自动采购不对具体商品设置数量，直接统一的设置一个数量即可」——
     逐商品 targets 退役 → **统一目标持有量** cfg.qty（0 = 不自动买）。
     老档迁移：有 targets 的档取其中最常见的非 0 值作为统一数量（就地一次性转换）。 */
  GAME.autoBuyCfg = function () {
    var s = GAME.state; if (!s || !s.settings) return null;
    var A = DATA.AUTO_BUY || {};
    if (!s.settings.autoBuy) {
      s.settings.autoBuy = { on: false, qty: 0, everyMin: A.defaultFreqMin || 10, last: 0 };
    }
    var c = s.settings.autoBuy;
    if (c.qty == null) {
      var _mig = 0, _cnt = {};
      for (var _k in (c.targets || {})) {
        var _v = Math.floor(Number(c.targets[_k]) || 0);
        if (_v > 0) { _cnt[_v] = (_cnt[_v] || 0) + 1; }
      }
      var _best = 0;
      Object.keys(_cnt).forEach(function (v) { if (!_best || _cnt[v] > _cnt[_best]) _best = v; });
      _mig = Number(_best) || 0;
      c.qty = _mig;
      delete c.targets;
    }
    if (c.everyMin == null) c.everyMin = A.defaultFreqMin || 10;
    return c;
  };
  GAME.doToggleAutoBuy = function () {
    var cfg = GAME.autoBuyCfg(); if (!cfg) return;
    cfg.on = !cfg.on;
    if (cfg.on) { cfg.last = 0; GAME.state.autoBuyInfo = { ok: true, msg: '已开启，待命', at: U.now() }; }
    else GAME.state.autoBuyInfo = { ok: false, msg: '已关闭', at: U.now() };
    GAME.refreshView();
  };
  GAME.doSetAutoBuy = function (k, v) {
    var cfg = GAME.autoBuyCfg(); if (!cfg) return;
    if (k === 'qty') cfg.qty = Math.max(0, Math.floor(Number(v) || 0));
    else if (k === 'everyMin') cfg.everyMin = Math.max(1, Math.floor(Number(v) || 10));
  };
  GAME.autoBuyOnce = function () {
    var s = GAME.state, cfg = GAME.autoBuyCfg();
    if (!cfg || !cfg.on) return { ok: false, msg: '未开启' };
    var want = Math.floor(cfg.qty || 0);
    if (want <= 0) return { ok: false, msg: '未设置统一采购数量（0 = 不自动买）' };
    var bought = 0, spent = 0;
    /* v91.72：统一数量 = 每种可购商品都补到 want 件（各自受每日上限 / 旧币钳制）。 */
    (DATA.ITEMS || []).forEach(function (it) {
      if (!it || !it.price || it.noShop || it.dropOnly || it.wonderOnly) return;
      if (!GAME.ui || !GAME.ui.SHOP_CATS || !GAME.ui.SHOP_CATS[it.type]) return;
      var id = it.id;
      var have = (s.items || {})[id] || 0;
      var need = want - have;
      if (need <= 0) return;
      var left = GAME.shopTodayLeft(id);          /* 每日购买上限余量 */
      var q = Math.min(need, left);
      if (q <= 0) return;
      var r = GAME.doShopping(id, q, true);        /* 静默：走同一出口（扣款/每日上限一致） */
      if (r && r.ok && r.bought > 0) { bought += r.bought; spent += r.bought * it.price * 100; }
    });
    if (spent > 0) GAME.log('🤖 自动采购：补货 ' + bought + ' 件（-' + GAME.utils.fmt(spent) + ' 旧币）');
    s.autoBuyInfo = { ok: bought > 0, msg: bought > 0 ? ('已补货 ' + bought + ' 件') : '待命', at: U.now() };
    return { ok: bought > 0, msg: s.autoBuyInfo.msg, bought: bought };
  };
  GAME.autoBuy = function () {
    var cfg = GAME.autoBuyCfg();
    if (!cfg || !cfg.on) return null;
    var now = U.now();
    if (now - (cfg.last || 0) < cfg.everyMin * 60000) return null;
    cfg.last = now;
    return GAME.autoBuyOnce();
  };

  /* ============================================================
   * v91.36（老板）：「增加**自动探索** —— 城中有任意空闲英雄和可用兵种时，
   *   每个城市均可向奇观派遣探索队。参考自动出征，但**不设固定英雄**。」
   * ------------------------------------------------------------
   * 口径：
   *   · 全局开关 + 频率（现实分钟）+ 每城每日上限；**逐城**尝试（每城各自抢一位空闲英雄）；
   *   · 目标 = 本星球（当前 activePlanet）今日奇观，须在途未满（DATA.WONDER_CFG.maxActive）；
   *   · 兵力 = `cfg.army`（逐兵种上限）∩ 城内实有；主角行动 = 奇观支持的第一个（或 cfg.act）。
   * ============================================================ */
  GAME.autoExploreCfg = function () {
    var s = GAME.state; if (!s || !s.settings) return null;
    var A = DATA.AUTO_EXPLORE || {};
    if (!s.settings.autoExplore) {
      s.settings.autoExplore = {
        on: false, act: null, everyMin: A.defaultFreqMin || 20, last: 0,
        dailyMax: (A.defaultDailyMax != null ? A.defaultDailyMax : 2),
        army: {},                    /* 逐兵种「自动探索数量」（0/缺 = 不自动派） */
        /* v91.84（老板「把行为链每一个选项走到头」）：**清层编成**。
           破层是一场真战斗（守军按层 8千~40万），与"带多少兵去采集"不是一套兵 ——
           只做采集的玩家（探索编成 0）此前会被"清层需兵"卡死，第一层永远破不了。
           本表单独设定；**留空 = 沿用探索编成**（老档/未设时行为不变）。 */
        clearArmy: {},
        today: {},                   /* { 城id: 今日已派次数 } · 随现实日归零 */
        todayKey: '',
        /* v91.81（老板「自动探索开发所有星球和城市选项」）：探索范围 = **排除表**（黑名单）。
           默认空 = 全域（兼容老档）；玩家在弹窗里取消勾选某星球/某城 → 记 1 = 不探索。 */
        offPlanets: {},              /* { pid: 1 } */
        offCities: {},               /* { cityId: 1 } */
        /* v91.82（老板「自动探索也要按城指定英雄」）—— 与自动出征同构：
           cityGen[cityId] = genId 表示**该城固定**用这位英雄；留空 = 该城不限。 */
        cityGen: {},
        genId: null,                 /* 全局兜底（界面只暴露「按城指定」，此键留作兼容/存档） */
        /* v91.84（老板「把行为链每一个选项走到头」）：**默认开**。
           原默认关 → 开局已清 0 层、所有行动全锁 → 自动探索永远只报「无可派行动」，
           链条断在第一步（奇观界面也看不出该去破层）。
           安全阀（防送死）：编成总兵力 < 该层「建议最小兵力」时**绝不出战**，
           只打"带够了兵"的那一层；清层**不占**每城每日探索次数，成功即当轮重试派队。 */
        autoClear: true,
        /* v92.1：奇观那边没活干时，**顺带派侦察去探路**（默认关）。
           挂机不该什么都推不动 —— 但也不该不打招呼就烧兵，所以做成显式开关，
           编成沿用「自动探索编成」，每城每日次数照吃。 */
        probe: false,
      };
    }
    var c = s.settings.autoExplore;
    if (c.everyMin == null) c.everyMin = A.defaultFreqMin || 20;
    if (c.dailyMax == null) c.dailyMax = (A.defaultDailyMax != null ? A.defaultDailyMax : 2);
    if (!c.army) c.army = {};
    if (!c.clearArmy || typeof c.clearArmy !== 'object') c.clearArmy = {};      /* v91.84 */
    if (!c.today) c.today = {};
    if (!c.offPlanets || typeof c.offPlanets !== 'object') c.offPlanets = {};   /* v91.81 */
    if (!c.offCities || typeof c.offCities !== 'object') c.offCities = {};      /* v91.81 */
    if (!c.cityGen || typeof c.cityGen !== 'object') c.cityGen = {};            /* v91.82 */
    if (c.autoClear == null) c.autoClear = true;                                /* v91.84 */
    if (c.probe == null) c.probe = false;                                       /* v92.1 */
    if (!c.cityGen || typeof c.cityGen !== 'object') c.cityGen = {};            /* v91.82 */
    return c;
  };
  /* 现实日归零（每城计数同翻）—— 与自动出征同轴。 */
  GAME.autoExploreRollDay = function (cfg) {
    if (!cfg) return null;
    var key = String(Math.floor(U.now() / 86400000));
    if (cfg.todayKey !== key) { cfg.todayKey = key; cfg.today = {}; }
    return cfg;
  };
  /* ============================================================
   * v91.81（老板：「自动探索，开发所有星球和城市选项 …… 目前限定为当前星球了」）——
   *   探索范围**唯一出口**：默认全域（排除表空 = 全部星球 + 全部城市都探索），
   *   玩家在「选择星球/城市」弹窗里取消勾选 → 记入排除表，该星球/该城不再派队。
   *   抽成独立函数是因为"哪些城参与"必须能被单独验证（留在 autoExplore 里会被
   *   频率节流的提前 return 挡住，永远测不到）。
   *   · inScope(pid)          —— 星球级（该球整体被排除则 false）
   *   · inScope(pid, cityId)  —— 城级（球被排除 或 该城被排除 → false）
   * ============================================================ */
  GAME.autoExploreInScope = function (cfg, pid, cityId) {
    cfg = cfg || GAME.autoExploreCfg();
    if (!cfg) return false;
    if (cfg.offPlanets && cfg.offPlanets[pid]) return false;
    if (cityId != null && cfg.offCities && cfg.offCities[cityId]) return false;
    return true;
  };
  /* 范围内星球数 / 城数（界面摘要用，可验证）。 */
  GAME.autoExploreScopeCount = function (cfg) {
    var s = GAME.state;
    cfg = cfg || GAME.autoExploreCfg();
    var planets = 0, cities = 0;
    if (!cfg || !s) return { planets: 0, cities: 0 };
    GAME.planetsOf().forEach(function (pl) {
      var cs = (s.cities || []).filter(function (c) { return GAME.pidOf(c) === pl.id; });
      if (!cs.length) return;
      if (!GAME.autoExploreInScope(cfg, pl.id)) return;
      planets++;
      cs.forEach(function (c) { if (GAME.autoExploreInScope(cfg, pl.id, c.id)) cities++; });
    });
    return { planets: planets, cities: cities };
  };
  /* ============================================================
   * v91.83（老板「奇观探索的行为链不对，全面复核」）—— **行为链收敛**。
   * 复核发现两条断链，均在"选行动"这一步：
   *   ① **开局死锁**：`wonderActGateOf` 最低门槛是 1 层（collect/study），
   *      而 `pl.wonderClearedLv` 现实日刷新后 = 0 → **所有行动全锁** →
   *      自动探索 100% 不工作，且界面只说"行动由系统随机"，看不出要清层。
   *   ② **随机硬撞**：v91.79 改成随机取行动后，**不校验本城能不能做到** ——
   *      `needArmy` 而玩家没设编成 → total=0 失败；`rescue` 的 `needLoad`
   *      （总负重 2 万）不满足 → wonderExplore 直接拒 → **整城跳过**。
   *      随机取到哪个算哪个，等于掷骰子决定这城探不探。
   * 修法：**先算可行集，再随机**（不是先随机再撞墙）。
   *   · `GAME.autoExploreActsFor(pid, city, cfg)` = 唯一出口，返回
   *     { feas:[可行行动…], blocked:[{id,name,why,kind}…] }；
   *   · `GAME._autoExploreActFit` = 单行动 × 本城 的编成/负重匹配；
   *   · 可行集为空 → 若开了「自动清层」（cfg.autoClear）则派兵打下一层，
   *     把链补上（清层 → 解锁行动 → 采集）；否则**带明确原因跳过**（不再静默）。
   * ============================================================ */
  /* 清层编成（唯一出口）：单独设了就用它，否则**沿用探索编成**（老档行为不变）。
     返回 null = 一套兵都没有（无法破层）。 */
  GAME.autoExploreClearComp = function (cfg) {
    cfg = cfg || GAME.autoExploreCfg();
    if (!cfg) return null;
    var src = (cfg.clearArmy && Object.keys(cfg.clearArmy).length) ? cfg.clearArmy : (cfg.army || {});
    var out = {}, any = false;
    for (var k in src) { var q = Math.max(0, Math.floor(src[k] || 0)); if (q > 0) { out[k] = q; any = true; } }
    return any ? out : null;
  };
  /* 单行动 × 本城 的编成匹配（含 needArmy / needLoad 两道门槛）。 */
  GAME._autoExploreActFit = function (city, cfg, actId, act, compOverride) {
    act = act || (DATA.WONDER_ACT_DEFS || {})[actId] || {};
    var army = {}, total = 0, load = 0;
    if (act.needArmy) {
      var comp = {}, has = false;
      var _src = compOverride || (cfg && cfg.army) || {};
      for (var ik in _src) {
        var iq = Math.max(0, Math.floor(_src[ik] || 0));
        if (iq > 0) { comp[ik] = iq; has = true; }
      }
      if (!has) return { ok: false, kind: 'nocomp', why: '未设定编成' };
      var m = GAME.autoMarchMatchCity(city, comp);
      if (!m.ok) {
        var why = m.reason === 'cap'
          ? ('总兵力 ' + U.fmt(m.need) + ' 超本城练兵场出征容量 ' + U.fmt(m.cap))
          : (((DATA.TROOPS[m.short] || {}).name || m.short) + ' 需 ' + U.fmt(m.need) + ' 现有 ' + U.fmt(m.have));
        return { ok: false, kind: m.reason, why: why };
      }
      army = m.army; total = m.total;
      for (var k2 in army) load += (army[k2] || 0) * (((DATA.TROOPS[k2] || {}).load) || 0);
    }
    /* v91.36：负重门槛（方舟救援须能"运回幸存者"）—— 与出征面板同一套 load 字段。 */
    if (act.needLoad && load < act.needLoad) {
      return { ok: false, kind: 'load',
        why: '队伍总负重 ' + U.fmt(load) + ' < 所需 ' + U.fmt(act.needLoad) };
    }
    return { ok: true, army: army, total: total, load: load };
  };
  /* ============================================================
   * v92.1：**自动探路**（挂机也能推进探索）
   * ------------------------------------------------------------
   * 老板：「我不想纯粹是挂机游戏……挂机资源不会对游戏产生决定性影响」。
   * 反过来说也一样成立：挂机不该什么都推不动。
   * 奇观探索队走的是固定点位，永远不会去"没去过的地方"——
   * 于是迷雾加进来以后，纯挂机的玩家地图会停在开局那一小圈。
   *
   * 这里补的是一条**可选**的探路队（cfg.probe，默认关）：
   * 奇观那边今天没活干时，派一队侦察去"已探明边缘的未探明格"。
   *
   * ⚠️ 为什么不直接派进纯黑里：玩家看不到它从哪过去，新亮的一片和旧亮区
   * 断开，像凭空开了一块图。从边缘出发，路径是连着的，看着才像"走出去"。
   * ⚠️ 吃每城每日次数（与奇观派队同一条闸）：不然 20 分钟一次能一路刷到全亮。
   * ============================================================ */
  GAME._autoProbeTargetOf = function (city, maxHops) {
    var F = GAME.fog;
    if (!F || !city) return -1;
    var pid = GAME.pidOf ? GAME.pidOf(city) : null;
    var SPn = (GAME.sphereOf && pid != null) ? GAME.sphereOf(pid) : GAME.sphere;
    if (!SPn || !SPn.hopsWithin || !SPn.adj) return -1;
    var ci = city.ci;
    if (ci == null || ci < 0) return -1;
    var ring = SPn.hopsWithin(ci, maxHops || 30);   /* BFS 顺序 = 由近及远 */
    for (var i = 0; i < ring.length; i++) {
      var c = ring[i];
      if (F.get(c) !== 0) continue;                 /* 已探明，跳过 */
      var nb = SPn.adj[c] || [];
      for (var k = 0; k < nb.length; k++) {
        if (F.get(nb[k]) > 0) return c;             /* 与已探明相邻 = 边缘 */
      }
    }
    return -1;
  };

  GAME._autoProbeCity = function (pid, city, cfg) {
    if (!cfg || !cfg.probe) return null;
    var tci = GAME._autoProbeTargetOf(city, 30);
    if (tci < 0) return { ok: false, msg: '「' + city.name + '」周边已无可探之处' };
    /* 编成走玩家自己设的「自动探索编成」—— 探路不该另开一套队伍配置。 */
    var comp = cfg.army || {}, army = {}, tot = 0;
    for (var id in comp) {
      var want = Math.max(0, Math.floor(comp[id] || 0));
      if (!want) continue;
      var have = Math.floor((city.army || {})[id] || 0);
      var n = Math.min(want, have);
      if (n > 0) { army[id] = n; tot += n; }
    }
    if (!tot) return { ok: false, msg: '「' + city.name + '」探路编成为空（先在自动探索里设编成）' };
    var gen = GAME.autoExplorePickGen ? GAME.autoExplorePickGen(cfg, city) : null;
    /* 侦查必须有主将（expedition/prepare 会拒）—— 这里先拦，给出能照着做的提示，
       别让玩家看到一句没头没尾的"请选择出征英雄"。 */
    if (!gen) return { ok: false, msg: '「' + city.name + '」没有可派的主将（自动探索里给这城指定英雄）' };
    var r = GAME.march.dispatch({ kind: 'wild', ci: tci }, 'scout', army,
      gen.id, null, { fromCityId: city.id });
    if (r && r.ok) return { ok: true, probe: true, msg: '「' + city.name + '」派队探路（去程 ' + U.durExact(Math.max(1, r.march ? (r.march.totalTime / GAME.timeScale()) : 1)) + '）' };
    return { ok: false, msg: (r && r.msg) || '探路失败' };
  };

  /* 本城 × 本星球奇观 的**可行行动集**（界面提示与自动派队共用同一出口）。 */
  GAME.autoExploreActsFor = function (pid, city, cfg) {
    var out = { feas: [], blocked: [], wonder: null };
    var wd = GAME.wonderOf ? GAME.wonderOf(pid) : null;
    out.wonder = wd;
    if (!wd) return out;
    (wd.acts || []).forEach(function (actId) {
      var act = (DATA.WONDER_ACT_DEFS || {})[actId] || {};
      var lock = GAME.wonderActLockOf(pid, actId);              /* 门槛层：未清层 → 锁 */
      if (lock) { out.blocked.push({ id: actId, name: act.name || actId, why: lock, kind: 'lock' }); return; }
      var f = GAME._autoExploreActFit(city, cfg, actId, act);   /* 能力：编成 / 负重 */
      if (!f.ok) { out.blocked.push({ id: actId, name: act.name || actId, why: f.why, kind: f.kind }); return; }
      out.feas.push({ id: actId, name: act.name || actId, army: f.army, total: f.total, load: f.load, act: act });
    });
    return out;
  };
