        if (x === 0 || y === 0 || x === w - 1 || y === h - 1) edge = true;
        else if ((GAME.map.terrainAt(x - 1, y) || 'plain') !== tt || (GAME.map.terrainAt(x + 1, y) || 'plain') !== tt
          || (GAME.map.terrainAt(x, y - 1) || 'plain') !== tt || (GAME.map.terrainAt(x, y + 1) || 'plain') !== tt) edge = true;
