    ridge: 1.5,             /* L1 山脉强度 */
    mountain: 'fold',       /* L1 山脉成因：fold 褶皱 / volcano 火山 / block 断块 / impact 撞击 */
    oceanDepth: 1.0,        /* L1 海深剖面（0.4 浅…1.6 深）*/
