      '<rect x="41" y="15" width="4.5" height="9" rx="1" fill="' + P.stMd + '"/>' +
      '<rect x="40.4" y="13.4" width="5.7" height="2.4" rx="1" fill="' + P.stLo + '"/>' +
      '<ellipse cx="43.5" cy="11.6" rx="3" ry="2" fill="#fff" opacity=".13"/>';
