      var _avSig = (s.ruler.name || '') + '|' + (s.ruler.gender || '') + '|' + (s.ruler.portraitSeed || '');
      if (av._sig !== _avSig) { av._sig = _avSig; av.innerHTML = GAME.portraits.html(rulerGen, 68); }
