      var pr = GAME.march.progressOf(m);
      var md = GAME.battle.modeOf(m.modeId);
      var gen = null;
      (s.generals || []).forEach(function (g) { if (g.id === m.genId) gen = g; });
      var n = 0;
      for (var k in m.army) n += m.army[k] || 0;
